{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyN1cUZbsA42GegWbk2SHfvJ"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":1,"metadata":{"id":"AYidOQrKGcMv","executionInfo":{"status":"ok","timestamp":1780500541073,"user_tz":-120,"elapsed":6422,"user":{"displayName":"Ala Berent","userId":"11033363761964370986"}}},"outputs":[],"source":["from torch import nn\n","\n","class Autoencoder(nn.Module):\n","  def __init__(self, input_dim, latent_dim):\n","    super()._init_()\n","\n","    self.encoder = nn.Sequential(\n","      nn.Linear(input_dim, 256),\n","      nn.ReLU(),\n","      nn.Linear(256, 128),\n","      nn.ReLU(),\n","      nn.Linear(128, latent_dim))\n","\n","    self.decoder = nn.Sequential(\n","      nn.Linear(latent_dim, 128),\n","      nn.ReLU(),\n","      nn.Linear(128, 256),\n","      nn.ReLU(),\n","      nn.Linear(256, input_dim))\n","\n","    def forward(self, x):\n","      z = self.encoder(x)\n","      reconstruction = self.decoder(z)\n","      return reconstruction"]}]}